n = int(input())
def go(r, cols, d1, d2):
    if r == n:
        return 1
    t = 0
    for c in range(n):
        if c not in cols and r - c not in d1 and r + c not in d2:
            t += go(r + 1, cols | {c}, d1 | {r - c}, d2 | {r + c})
    return t
