n, amount = map(int, input().split())
coins = list(map(int, input().split()))
INF = float('inf')
dp = [0] + [INF] * amount
for a in range(1, amount + 1):
    for c in coins:
        if c <= a and dp[a - c] + 1 < dp[a]:
            dp[a] = dp[a - c] + 1
